// Verify Telegram secret_token header (fail-closed). The webhook
// headerAuth credential is the primary gate; this node adds a second check
// against the container env value before any payload handling.
const inp = $input.first().json;
const body = inp.body;
const headers = inp.headers ? inp.headers : {};
const secret = $env.TELEGRAM_WEBHOOK_SECRET ? $env.TELEGRAM_WEBHOOK_SECRET : '';
if (!secret) { throw new Error('TELEGRAM_WEBHOOK_SECRET is not configured - refusing all traffic'); }
const got = headers['x-telegram-bot-api-secret-token'] ? String(headers['x-telegram-bot-api-secret-token']).trim() : '';
if (!got) { throw new Error('Missing Telegram secret header - rejected'); }
function safeEqual(a, b) {
  const x = String(a);
  const y = String(b);
  if (x.length !== y.length) { return false; }
  let d = 0;
  for (let i = 0; i < x.length; i++) { d |= x.charCodeAt(i) ^ y.charCodeAt(i); }
  return d === 0;
}
if (!safeEqual(got, secret)) { throw new Error('Invalid Telegram secret header - rejected'); }
return [{ json: { provider: 'telegram', verified: true, body: body, headers: headers } }];

// Extract patient payload from a Telegram Update (table dispatch,
// ternaries only). Supports text, voice, button taps, photo, document,
// video and location updates.
const inp = $input.first().json;
const body = inp.body;
const upd = body.edited_message ? body.edited_message : (body.message ? body.message : null);
const cb = body.callback_query ? body.callback_query : null;
let messageId = 'tg_' + Date.now();
let chatId = 'unknown';
let userId = 'unknown';
let pushName = 'esteemed patient';
let textMessage = '';
let isAudio = false;
let voiceFileId = null;
if (cb) {
  const rawCb = cb.data ? String(cb.data) : '';
  const isConfirmTap = rawCb.indexOf('confirm') === 0;
  const rateM = rawCb.match(/^rate:(\d)$/);
  const isRateTap = !!rateM;
  messageId = cb.id ? cb.id : messageId;
  const from = cb.from ? cb.from : {};
  userId = from.id ? String(from.id) : userId;
  pushName = from.first_name ? from.first_name : pushName;
  chatId = cb.message ? (cb.message.chat ? String(cb.message.chat.id) : chatId) : chatId;
  textMessage = isConfirmTap ? 'تمام' : (isRateTap ? ('RATING:' + rateM[1]) : (cb.data ? String(cb.data) : ''));
} else if (upd) {
  messageId = upd.message_id ? ('tg_' + String(upd.message_id)) : messageId;
  const from = upd.from ? upd.from : {};
  userId = from.id ? String(from.id) : userId;
  pushName = from.first_name ? from.first_name : pushName;
  chatId = upd.chat ? String(upd.chat.id) : chatId;
  const KIND = {
    text: (m) => m.text ? String(m.text) : '',
    voice: (m) => '',
    photo: (m) => m.caption ? ('[patient sent image: ' + m.caption + ']') : '[patient sent image]',
    document: (m) => '[patient sent document]',
    video: (m) => m.caption ? ('[patient sent video: ' + m.caption + ']') : '[patient sent video]',
    location: (m) => m.location ? ('[patient geo location: Lat ' + m.location.latitude + ', Lng ' + m.location.longitude + ']') : '[patient geo location]',
    sticker: (m) => '[patient sent sticker]',
    contact: (m) => m.contact ? ('[patient shared contact: ' + (m.contact.phone_number ? m.contact.phone_number : 'no number') + ']') : '[patient shared contact]',
    unknown: (m) => '[unsupported message type]'
  };
  const kind = upd.text ? 'text' : (upd.voice ? 'voice' : (upd.photo ? 'photo' : (upd.document ? 'document' : (upd.video ? 'video' : (upd.location ? 'location' : (upd.sticker ? 'sticker' : (upd.contact ? 'contact' : 'unknown')))))));
  const fn = KIND[kind] ? KIND[kind] : KIND.unknown;
  textMessage = fn(upd);
  isAudio = kind === 'voice';
  voiceFileId = kind === 'voice' ? (upd.voice.file_id ? upd.voice.file_id : null) : null;
} else {
  textMessage = '[unsupported update type]';
}
const isTap = (typeof cb !== 'undefined' && cb) ? true : false;
return [{ json: { messageId: messageId, chatId: chatId, userId: userId, pushName: pushName, provider: 'telegram', isAudio: isAudio, voiceFileId: voiceFileId, textMessage: String(textMessage).trim(), viaButtonTap: isTap, callbackId: (typeof cb !== 'undefined' && cb && cb.id) ? String(cb.id) : '', timestamp: new Date().toISOString() } }];

// Direct text merge handling non-audio messages.
const prev = $('Extract Telegram Payload').first().json;
return [{ json: { chatId: prev.chatId, pushName: prev.pushName, provider: prev.provider, finalMessage: prev.textMessage ? prev.textMessage : 'hello', wasVoice: false, isAudioMuffled: false } }];

// Flag explicit confirmation replies (tight opt-in vocabulary only).
const inp = $input.first().json;
const t = inp.finalMessage ? String(inp.finalMessage).trim().toLowerCase() : '';
const rx = /^(تمام|تم|اوك|ok|yes|موافق|تاكيد|تأكيد|اكيد|أكيد|ماشي|نعم|ايوه|ايوة|1|👍)(\s|[!\\uFF01.،,👍]|$)/;
const hit = rx.test(t);
const tx = (inp.finalMessage ? String(inp.finalMessage) : '').toLowerCase();
const hasAction = /(احجز|الغي|الغاء|انقل|انتظار|waitlist|احجزلي|شكوى|طوارئ|نزيف|book|cancel|reschedul)/.test(tx);
const hits = ['سعر|بكام|اسعار|تكلفة|price|cost', 'مواعيد|بتفتح|بتقفلو|دوام|hours|open', 'دكتور|اطباء|doctor', 'عنوان|فين|مكان|address|location', 'خدمات|services'].filter((p) => new RegExp(p).test(tx)).length;
const isMulti = !hasAction && hits >= 2;
const closeRx = /^(شكرا|تسلم|ممنون|متشكر|تمام شكرا|ميرسي|thanks|thank you|مع السلامة|باي|bye)([\s!\.،,]|(شكرا|تسلم|ممنون|متشكر|ميرسي|thanks|thank you|مع السلامة|باي|bye))*$/;
const isClose = closeRx.test(tx.trim()) && !hasAction;
return [{ json: { chatId: inp.chatId ? String(inp.chatId) : 'unknown', pushName: inp.pushName ? String(inp.pushName) : '', provider: inp.provider ? String(inp.provider) : '', finalMessage: inp.finalMessage ? String(inp.finalMessage) : '', wasVoice: !!inp.wasVoice, isAudioMuffled: !!inp.isAudioMuffled, confirmed: hit, at: Date.now(), severe: !!inp.severe, multi: isMulti, closing: isClose } }];

// Fan own reminder map to parsed records (single input item).
const j = $input.first().json;
const parseRec = (v) => {
  if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return null; } }
  return (v && typeof v === 'object') ? v : null;
};
return Object.keys(j || {})
  .filter((k) => String(k).indexOf('remind:') === 0)
  .map((k) => parseRec(j[k]))
  .filter((rec) => rec && rec.appointmentISO)
  .map((rec) => ({ json: { record: rec } }));

// Stamp confirmedAt on the record ($input carries it).
const rec = $input.first().json.record;
if (!rec || !rec.chatId) { return []; }
return [{ json: { ...rec, confirmedAt: Date.now() } }];

// Join the waitlist when the patient asks (انتظار/waitlist), else pass through.
const inp = $input.first().json;
const t = inp.finalMessage ? String(inp.finalMessage).trim().toLowerCase() : '';
const join = t.indexOf('انتظار') !== -1 || t.indexOf('waitlist') !== -1 || t.indexOf('wait list') !== -1;
if (!join) { return []; }
return [{ json: { chatId: inp.chatId ? String(inp.chatId) : 'unknown', pushName: inp.pushName || '',
  join: join, entry: join ? JSON.stringify({ chatId: String(inp.chatId), name: inp.pushName || '', at: Date.now() }) : '',
  finalMessage: inp.finalMessage || '', wasVoice: !!inp.wasVoice, isAudioMuffled: !!inp.isAudioMuffled } }];

// Severe-emergency triage gate (DentAI-style): always forwards, flags severe.
// Runs BEFORE Track Confirmation so the flag travels WITH the item (order-proof).
const inp = $input.first().json;
const t = inp.finalMessage ? String(inp.finalMessage).toLowerCase() : '';
const severeRx = /(نزيف|نزف|bleeding|كسر|broken|fracture|خراج|abscess|ورم يزيد|حادث|طوارئ|emergency|لا يحتمل|مغمى|اغماء|اختناق|choking)/;
const humanRx = /(عايز اكلم|عاوز اكلم|ابغى اكلم|بدي احكي|talk to (a )?(human|person|staff|manager|someone)|speak to|call (the )?staff|human request|موظف بشري|حد مسؤول|وصلني بموظف|كلمني حد)/;
const severe = severeRx.test(t);
const humanReq = humanRx.test(t);
const out = {};
for (const k of Object.keys(inp)) { out[k] = inp[k]; }
out.severe = (severe || humanReq);
out.kind = severe ? 'emergency' : 'human-request';
return [{ json: out }];

// Deterministic answer for pure-knowledge multi-questions (no agent needed).
const inp = $input.first().json;
const rows = (inp.error === undefined && Array.isArray(inp.data)) ? inp.data : [];
const tx = ($('Track Confirmation Intent').item.json.finalMessage || '').toLowerCase();
const svc = rows.filter((r) => r.kind === 'service');
const priceFor = (keys) => {
  const hit = svc.find((r) => keys.some((k) => String(r.name).toLowerCase().indexOf(k) !== -1));
  return hit ? (arName(hit.name) + ' ' + hit.price + ' جنيه') : '';
};
const AR = {'General exam': 'الكشف العام', 'Cleaning and polishing': 'التنظيف والتلميع', 'Filling per tooth': 'الحشو', 'Root canal': 'علاج الجذور', 'Braces consult': 'استشارة التقويم', 'Implant consult': 'استشارة الزراعة', 'Whitening': 'التبييض'};
const arName = (en) => AR[en] || en;
const parts = [];
if (/سعر|بكام|اسعار|تكلفة|price|cost/.test(tx)) {
  const items = [];
  const wants = [];
  if (/تنظيف|تلميع|clean/.test(tx)) { wants.push(['cleaning']); }
  if (/حشو|fill/.test(tx)) { wants.push(['filling']); }
  if (/تقويم|braces|orth/.test(tx)) { wants.push(['braces']); }
  if (/زراعة|implant/.test(tx)) { wants.push(['implant']); }
  if (/تبييض|whiten/.test(tx)) { wants.push(['whiten']); }
  if (/كشف|exam|check/.test(tx)) { wants.push(['exam']); }
  if (!wants.length) {
    parts.push('أسعارنا: ' + svc.map((r) => arName(r.name) + ' ' + r.price + ' جنيه').join('، '));
  } else {
    wants.forEach((w) => { const p = priceFor(w); if (p) { items.push(p); } });
    if (items.length) { parts.push(items.join('، ')); }
  }
}
if (/مواعيد|بتفتح|بتقفلو|دوام|hours|open/.test(tx)) { parts.push('مواعيدنا السبت إلى الخميس 10:00-22:00، الجمعة 16:00-22:00'); }
if (/دكتور|اطباء|doctor/.test(tx)) {
  const docs = rows.filter((r) => r.kind === 'doctor').map((r) => r.name + ' (' + String(r.info || '').split('|')[0] + ')');
  if (docs.length) { parts.push('أطباؤنا: ' + docs.join('، ')); }
}
if (/عنوان|فين|مكان|address|location/.test(tx)) { parts.push('العنوان: القاهرة — العنوان التجريبي'); }
if (!parts.length) { return []; }
return [{ json: { finalMessage: parts.join('. ') } }];

// LLM-output validation (world-class contract enforcement): if the booking tool
// offered verified alternatives and the agent reply omits them, substitute the
// deterministic message. Otherwise pass the agent reply through untouched.
const cache = $input.first().json;
const agentOut = ($('AI Clinic Receptionist Agent').item.json.output || '').trim();
let alts = [];
try {
  const raw = (cache && (cache.value !== undefined ? cache.value : (cache.data !== undefined ? cache.data : cache.propertyName))) || null;
  const parsed = (typeof raw === 'string') ? JSON.parse(raw) : raw;
  if (parsed && Array.isArray(parsed.alternatives)) { alts = parsed.alternatives; }
} catch (e) { alts = []; }
const req = (() => { try {
  const raw = (cache && (cache.value !== undefined ? cache.value : (cache.data !== undefined ? cache.data : cache.propertyName))) || null;
  const parsed = (typeof raw === 'string') ? JSON.parse(raw) : raw;
  return (parsed && parsed.requested) || null; } catch (e) { return null; } })();
if (!alts.length || !req) { return [{ json: { output: agentOut } }]; }
const leakRx = /(we need|policy:|instruction|need to|deliberat|the tool|slotkey|eventid)/i;
const hit = alts.some((a) => agentOut.indexOf(a.time) !== -1) && agentOut.length < 300 && !leakRx.test(agentOut);
if (hit) { return [{ json: { output: agentOut } }]; }
const altTxt = alts.map((a) => a.date + ' الساعة ' + a.time).join(' أو ');
return [{ json: { output: 'الميعاد ' + req.time + ' غير متاح. متاح ' + altTxt + '، أيهما يناسبك؟',
  validated: true } }];
